package com.jnapanam.sportszone.payment.controller;import com.fasterxml.jackson.databind.ObjectMapper;import com.jnapanam.sportszone.common.exception.BadRequestException;import com.jnapanam.sportszone.payment.service.PaymentService;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/public/payments/webhooks")public class PaymentWebhookController{private final PaymentService service;private final ObjectMapper json;public PaymentWebhookController(PaymentService s,ObjectMapper j){service=s;json=j;}@PostMapping("/razorpay")@ResponseStatus(HttpStatus.NO_CONTENT)public void razorpay(@RequestHeader("X-Razorpay-Event-Id")String eventId,@RequestHeader("X-Razorpay-Signature")String signature,@RequestBody String body){try{service.webhook(eventId,signature,body,json.readTree(body));}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new BadRequestException("Invalid webhook payload");}}}
